#!/usr/bin/env python3
"""Selected evidence-backed reskins and original Mystara-compatible expedition gear."""
import json,re
from pathlib import Path
import yaml
ROOT=Path(__file__).resolve().parents[1];folder=ROOT/'catalog/settings/mystara-frontiers';folder.mkdir(parents=True,exist_ok=True)
def save(p,d):p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');p.with_suffix('.yaml').write_text(yaml.safe_dump(d,allow_unicode=True,sort_keys=False))
refs=[{'id':'champions','url':'https://en.wikipedia.org/wiki/Champions_of_Mystara','label':'Champions of Mystara: Heroes of the Princess Ark (1993)','source_kind':'bibliography','note':'Hero’s Journal, Explorer’s Manual and Designer’s Manual are tracked separately below; not fully audited.'},
 {'id':'skyships','url':'https://www.pandius.com/knwnskys.html','label':'Known Mystara Skyships','author':'Håvard','source_kind':'fan-source-index','note':'Separates source groupings, some explicitly invented names and later fan ships; no blanket canon status.'},
 {'id':'dawn','url':'https://en.wikipedia.org/wiki/Dawn_of_the_Emperors%3A_Thyatis_and_Alphatia','label':'Dawn of the Emperors: Thyatis and Alphatia','source_kind':'bibliography'},
 {'id':'thyatian-gear','url':'https://pandius.com/thylcamp.html','label':'Thyatian legions campaign ideas','source_kind':'fan-campaign-equipment-list','note':'Gladius, pugio, pila, scutum and lorica are secondary campaign leads, not verified original book pages.'},
 {'id':'thyatian-uniforms','url':'https://www.pandius.com/thaf1018.html','label':'Thyatian Armed Forces AC 1018','source_kind':'fan-expansion','note':'Uniform and cloak style is source-supported; no historical accuracy or mandatory ethnicity implied.'},
 {'id':'alphatian-library','url':'https://pandius.com/TheKingdomsOfAlphatia.pdf','label':'The Kingdoms of Alphatia','source_kind':'fan-setting-book-index','note':'Librarian robe and mirror of messaging are fan-reference leads; original lesser versions below are independent designs.'},
 {'id':'atruaghin-equipment','url':'https://www.pandius.com/atruitem.html','label':'Weapons and Equipment of the Atruaghin Clans','author':'Håvard','source_kind':'fan-gazetteer-item-index','note':'Separates gazetteer-reported items from author-created equipment. Original GAZ14 pages not inspected. Do not carry over ancestry bonuses or blanket alignment traits.'},
 {'id':'atruaghin-guide','url':'https://www.pandius.com/guide/atruagh.html','label':'Newbie’s Guide: Atruaghin','source_kind':'fan-setting-summary','note':'Five fictional clans, not five interchangeable real Indigenous nations. Older stereotyped depictions are not imported as character mechanics.'},
 {'id':'never-alone','url':'https://www.neveralonegame.com/never-alone','label':'Never Alone / Kisima Ingitchuna','source_kind':'official-game-page','cultural_context':'Made in collaboration with Iñupiat people of Alaska; the bola is attested as a puzzle tool. Atruaghin adaptations are new fiction, not Iñupiat artifacts.'},
 {'id':'mulaka','url':'https://www.lienzo.mx/prensa/mulaka.html','label':'Mulaka','source_kind':'developer-press-kit','cultural_context':'Lienzo’s game draws on Rarámuri culture of northern Mexico. New travel-gear concepts here are project inventions, not claimed game items or authentic sacred objects.'},
 {'id':'rivers','url':'https://www.elizabethlapensee.com/games/','label':'When Rivers Were Trails','source_kind':'creator-portfolio','cultural_context':'An Indigenous-led game about displacement and inter-nation encounters. Used for travel/cooperation themes, not extraction of ceremonial material.'}]
entities=[]
def entity(kind,key,label,aliases=(),parents=(),note=''):
 entities.append({'id':kind+':'+key,'kind':kind,'label':label,'aliases':list(aliases),'parent_ids':list(parents),'note':note})
entity('topic','mystara-frontiers','Mystara expedition and regional equipment',('Mystara frontiers',))
entity('publication','champions-mystara','Champions of Mystara',('Heroes of the Princess Ark',))
entity('publication','dawn-emperors','Dawn of the Emperors',('Thyatis and Alphatia',))
entity('publication','gaz14','GAZ14: The Atruaghin Clans',('GAZ14',))
entity('culture','alphatian','Alphatian',note='Fictional Mystaran culture. No automatic class, alignment or spellcasting proficiency.')
for key in ['bear','horse','elk','turtle','tiger']:
 entity('region','atruaghin-'+key,'Children of the '+key.title(),parents=('region:atruaghin',),note='Fictional GAZ14 clan region, verified against the fan source index; no racial trait or alignment inferred.')
 entity('culture','atruaghin-'+key,'Atruaghin '+key.title()+' Clan',parents=('region:atruaghin-'+key,),note='Fictional clan association. This is not an authentic label for a real Indigenous nation.')
for k,l in [('never-alone','Never Alone (Kisima Ingitchuna)'),('mulaka','Mulaka'),('when-rivers-were-trails','When Rivers Were Trails')]:entity('game',k,l)
items=[];slug=lambda t:re.sub(r'[^a-z0-9]+','-',t.casefold()).strip('-')
def associations(ref,region=None,culture=None):
 ev={'url':next(r['url'] for r in refs if r['id']==ref)};a=[{'entity_id':'setting:mystara','role':'setting','status':'project-setting-adaptation','evidence':ev}]
 if region:a.append({'entity_id':'region:'+region,'role':'cultural-association','status':'editorial-fantasy-campaign-association','evidence':ev})
 if culture:a.append({'entity_id':'culture:'+culture,'role':'cultural-association','status':'editorial-fantasy-campaign-association','evidence':ev})
 return a
def add(name,ref,pub,typ,icon,value,tldr,details,changes,creative,region=None,culture=None,base=None,magic=False,rarity=None,attune=False,source_note=None):
 row={'id':'mystara-frontiers:'+slug(name),'name':name,'evidence_ref':ref,'entity_id':pub,'type':typ,'icon':icon,'estimated_value_gp':value,'tldr':tldr,'details':details,'changes':changes,'creative':creative,'flavor':'Built for a journey whose map is still unfinished.','base_item_id':base,'magic':magic,'rarity':rarity,'attunement':attune,'mode':'original-homebrew-adaptation' if magic or not base else '2024-equipment-reskin','associations':associations(ref,region,culture),'source_note':source_note or 'Selected fan reference or thematic inspiration; original book pages and canonical powers remain unverified.'};items.append(row);return row
baseitems={r['id']:r for r in map(json.loads,(ROOT/'catalog/items.jsonl').read_text().splitlines())}
for name,base,icon,ref,region,culture in [
 ('Thyatian Gladius','shortsword','sword','thyatian-gear','thyatis','thyatian'),('Thyatian Pugio','dagger','dagger','thyatian-gear','thyatis','thyatian'),('Thyatian Pilum','javelin','spear','thyatian-gear','thyatis','thyatian'),('Thyatian Scutum','shield','shield','thyatian-gear','thyatis','thyatian'),
 ('Horse Clan Buffalo Spear','spear','spear','atruaghin-equipment','atruaghin-horse','atruaghin-horse'),('Turtle Clan Harpoon','javelin','spear','atruaghin-equipment','atruaghin-turtle','atruaghin-turtle'),('Atruaghin Bone Dagger','dagger','dagger','atruaghin-equipment','atruaghin',None),('Atruaghin Stone Handaxe','handaxe','axe','atruaghin-equipment','atruaghin',None),('Elk Clan Shortbow','shortbow','bow','atruaghin-equipment','atruaghin-elk','atruaghin-elk'),('Horse Clan Leather','leather-armor','light-armor','atruaghin-equipment','atruaghin-horse','atruaghin-horse'),
 ('Bear Clan Trade Basket','basket','container','atruaghin-guide','atruaghin-bear','atruaghin-bear'),('Bear Clan Pottery Jug','jug','container','atruaghin-guide','atruaghin-bear','atruaghin-bear')]:
 iid='open5e-srd-2024:srd-2024_'+base;b=baseitems[iid];values=b['valuation']['base_values'];v=values[0]['amount_gp'] if values else 5
 add(name,ref,'publication:dawn-emperors' if region=='thyatis' else 'publication:gaz14',b['type'],icon,v,'Uses the standard 2024 '+b['name']+' profile.',f'Use the 2024 {b["name"]} rules, properties, capacity and normal training requirements. This regional draft adds no automatic damage bonus, cultural proficiency, brittle-material penalty, chain pull, impalement or harvesting requirement. Material and decoration are cosmetic unless the DM rules otherwise.','Replaces legacy edition and cultural bonuses with the named SRD profile. Bear trade goods are new campaign-style proposals based on craft themes, not named canonical artifacts.','Offer it as a trade sample or local commission. Social outcomes and identification remain DM rulings.',region,culture,iid)
for name,ref,pub,typ,icon,value,tldr,details,region,culture in [
 ('Thyatian Unit Surcoat','thyatian-uniforms','publication:dawn-emperors','clothing','clothing',3,'A unit-marked outer garment without armor bonuses.','Mundane clothing bearing a commissioned unit pattern. It grants no AC, disguise success, rank or legal authority. Recognition, impersonation and consequences are handled by the DM.','thyatis','thyatian'),
 ('Thyatian Weather Cloak','thyatian-uniforms','publication:dawn-emperors','cloak','cloak',5,'A practical travel cloak in a unit’s chosen colors.','Mundane cloak for ordinary wind and light rain. It grants no damage resistance, cold immunity, Stealth advantage or additional armor protection. Severe weather still uses the campaign’s normal rules.','thyatis','thyatian'),
 ('Alphatian Court Silk Robe','dawn','publication:dawn-emperors','clothing','clothing',50,'A luxury court garment; magic is not implied.','Mundane fine clothing. It grants no AC, spellcasting, rank or automatic welcome at court. A courtier may recognize its commission or maker at the DM’s discretion.','alphatia','alphatian'),
 ('Horse Clan Tack Repair Roll','atruaghin-guide','publication:gaz14','tools','tools',10,'Maintain ordinary harness and pack straps.','A leatherworking supply roll with small repair materials. It replaces no tool proficiency and does not heal mounts or repair magic items. Repairs follow normal crafting/tool adjudication and consume supplies as the DM determines.','atruaghin-horse','atruaghin-horse'),
 ('Turtle Clan Fishing Line Case','atruaghin-guide','publication:gaz14','adventuring-gear','container',5,'Keep fishing lines and hooks organized for travel.','A dry case for ordinary lines and hooks. The case supplies no food automatically and grants no guaranteed fishing success or underwater breathing. Fish availability and forage checks remain normal campaign matters.','atruaghin-turtle','atruaghin-turtle')]:
 add(name,ref,pub,typ,icon,value,tldr,details,'Original functional proposal from a regional theme; no official sourcebook mechanics or authentic real-world cultural status claimed.','Use it during downtime and travel. It opens a practical task rather than automatically resolving it.',region,culture)
add('Plateau Trail Bola','never-alone','game:never-alone','adventuring-gear','rope',25,'A limited throwing tool for slowing one pursuer.', 'As a Utilize action, throw the bola at one Small or Medium creature within 20 feet. It makes a DC 12 Dexterity saving throw. On a failure its Speed is reduced by 10 feet until the end of its next turn, to a minimum of 0. It is not Grappled, Restrained or Prone. The bola lands in the target’s space and must be recovered before reuse. It deals no damage.', 'Original lesser puzzle-tool-inspired adaptation. Not Nuna’s actual named weapon, authentic Iñupiat equipment statistics, or an official GAZ14 item.', 'Buy time during a retreat; it does not stop a creature from attacking or teleporting.','atruaghin-horse','atruaghin-horse',source_note='Official Never Alone page attests a bola. The Atruaghin placement and every rule here are new fictional project choices.')
add('Highland Runner’s Sandals','mulaka','game:mulaka','boots','boots',400,'A brief burst of sure-footed travel.', 'Requires attunement. Once per Long Rest, as a Bonus Action, ignore Difficult Terrain caused by loose natural stones and shallow mud until the end of your turn. Your Speed does not increase, and this does not ignore damaging terrain, magical restraints, climbing checks or liquid deep enough to require swimming.', 'Original travel-themed invention; not an attested Mulaka item or a Rarámuri ceremonial object.', 'Cross an uneven stretch while keeping your action for another task.','atruaghin-elk','atruaghin-elk',magic=True,rarity='uncommon',attune=True,source_note='Mulaka supplies terrain/travel inspiration only. No source-game item name or real cultural artifact is being claimed.')
add('River Companions’ Line','rivers','game:when-rivers-were-trails','adventuring-gear','rope',10,'A shared rope for deliberate river crossings.', 'Uses the 2024 Rope rules. Markings let companions agree on hand signals before crossing. It grants no Swim Speed, automatic rescue, special knot strength or immunity to currents; the DM resolves checks normally.', 'Original cooperation-themed gear inspired by a creator-described travel game; not a documented Anishinaabe artifact or source-game item.', 'Agree on a release signal before entering moving water. In play, terrain and party choices remain consequential.','atruaghin-turtle','atruaghin-turtle',base='open5e-srd-2024:srd-2024_rope',source_note='When Rivers Were Trails supplies cooperation and travel themes only, not this item’s identity or rules.')
add('Alphatian Librarian’s Robe (Lesser)','alphatian-library','publication:dawn-emperors','clothing','clothing',4000,'Consult one previously catalogued page at a distance.', 'Requires attunement. During a Long Rest, touch and designate one nonmagical book you own as your reference book. Once per Long Rest, as a Magic action while wearing the robe, view a mental image of one page you have previously seen in that book, provided the book remains on the same plane. The image lasts 1 minute. It cannot show changed text, decipher a language, copy a spell into a spellbook, or cast a spell. Designating another book ends the old link.', 'Independent lesser design replaces fan-described broad remote library access with one familiar page. It does not certify the item as canonical Dawn of the Emperors content.', 'Recall a map legend while exploring; a new page or hidden alteration still requires visiting the book.','alphatia','alphatian',magic=True,rarity='rare',attune=True)
add('Alphatian Message Mirror (Lesser)','alphatian-library','publication:dawn-emperors','wondrous-item','gear',400,'Send a short magical message once per day.', 'Requires attunement. Once per Long Rest, while holding this mirror, cast Message without components or a spell slot, using its normal casting time, range and all other limits. The recipient is not compelled to answer. This does not create a permanent paired-mirror connection or transmit images.', 'Original lesser spell-based version of a fan-index messaging mirror; no unlimited remote surveillance.', 'Whisper a brief warning through an ordinary barrier within the spell’s limits.','alphatia','alphatian',magic=True,rarity='uncommon',attune=True)
add('Skyfarer’s Safety Tether','skyships','publication:champions-mystara','wondrous-item','rope',400,'A one-use magical arrest can stop a deck fall.', 'Requires attunement. Once per Long Rest, when you fall within 30 feet of a fixed anchor to which the tether is secured, use your Reaction to halt the fall at the tether’s full length, taking no damage from that fall. You remain suspended and cannot move beyond the tether. It supports only you and your carried equipment. Securing or releasing it requires a Utilize action. It cannot anchor to a held object, creature or another tether.', 'Original skyship safety device inspired by expedition play; not a verified Champions of Mystara item.', 'Secure the anchor before climbing the rigging. A severed or unsecured line cannot help.','alphatia','alphatian',magic=True,rarity='uncommon',attune=True)
for name,cost,length,width,crew,passengers,speed in [('Alphatian Courier Skyship',50000,60,15,6,8,30),('Mystaran Survey Sky Barge',40000,50,20,5,12,20)]:
 row=add(name,'champions','publication:champions-mystara','air-vehicle','waterborne-vehicle',cost,'An original crewed skyship proposal for expedition campaigns.',f'Original 2024 vehicle proposal, requiring DM approval. Flying Speed {speed} feet while at least {crew} trained crew work aboard; maximum {passengers} passengers in addition to crew and 2 tons of cargo. No space travel, plane travel, hover when uncrewed, or automatic weapon systems. In combat, one helmsman uses an action to direct the vessel’s movement on their turn; it moves only once per round and grants no extra creature actions. Damage, collisions, adverse weather and loss of propulsion require agreed vehicle rules before use.','Independent lower-power ship template. Not the Princess Ark’s canonical statistics or a complete Champions skyship-building rules conversion.','Use as a mobile expedition base; crew, supplies, mooring rights and dangerous weather create ongoing needs.','alphatia' if 'Alphatian' in name else None,'alphatian' if 'Alphatian' in name else None,magic=True,rarity='legendary')
 row['record_kind']='vehicle';row['vehicle']={'kind':'skyship','length_ft':length,'width_ft':width,'crew_minimum':crew,'passengers':passengers,'cargo_tons':2,'flying_speed_ft':speed,'upkeep_gp_per_30_days':'250','upkeep_excludes':['crew-wages','fuel-or-magical-supplies','dock-fees','major-repairs'],'armor_class':None,'hit_points':None,'damage_threshold':None,'status':'original-design-needs-vehicle-rules-review'}
pack={'schema_version':1,'id':'mystara-frontiers-drafts','label':'Mystara regional and skyship project drafts','theme':'mystara-frontiers','topic_entity_id':'topic:mystara-frontiers','coverage':'Selected regional reskins, original travel gear, lesser Alphatian magic and two original skyships. No full GAZ14, Dawn of the Emperors or Champions boxed-set audit. Game-inspired gear is new fiction, not authentic cultural artifacts.','sources':refs,'entities':entities,'items':items}
save(folder/'research-pack.json',pack)
save(folder/'research-queue.json',{'workstreams':[{'id':key,'label':label,'status':status,'original_book_item_audit_complete':False} for key,label,status in [('champions-mystara','Champions of Mystara: Heroes of the Princess Ark','bibliography-selected-skyship-leads-two-original-designs'),('dawn-emperors','Dawn of the Emperors: Thyatis and Alphatia','selected-regional-gear-and-fan-magic-drafts'),('gaz14','GAZ14: The Atruaghin Clans','five-clans-corrected-selected-item-mappings-expanded'),('indigenous-game-research','Never Alone / Mulaka / When Rivers Were Trails','creator-sources-checked-three-explicitly-fictional-theme-adaptations')]],'champions_component_audits':[{'label':s,'status':'queued-original-book-audit'} for s in ['Hero’s Journal','Explorer’s Manual','Designer’s Manual']],'context_policy':'Keep Iñupiat, Rarámuri and Anishinaabe contexts distinct. No ancestry-based proficiency or alignment; no sacred tradition presented as generic loot.'})
print('Mystara frontier drafts',len(items))
